 brain:'<path d="M12 18V5a3 3 0 0 0-6 0 4 4 0 0 0-3 6 4 4 0 0 0 3 6 3 3 0 0 0 6 1Zm0 0V5a3 3 0 0 1 6 0 4 4 0 0 1 3 6 4 4 0 0 1-3 6 3 3 0 0 1-6 1Z"/><path d="M8 9 6 11m10-2 2 2M8 15 6 13m10 2 2-2"/>',
 circle:'<circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
